-- World infrastructure: reusable assets and directed links.
-- This migration intentionally creates the schema only; it does not seed towers,
-- satellites, the headquarters, coordinates, or connections.

CREATE TABLE IF NOT EXISTS public."worldInfrastructure" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" text NOT NULL UNIQUE,
  "name" text NOT NULL,
  "kind" text NOT NULL,
  "worldLocationId" integer NULL,
  "businessId" integer NULL,
  "description" text NULL,
  "foundingHistory" text NULL,
  "constructionType" text NULL,
  "coverage" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "details" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "operationalStatus" text NOT NULL DEFAULT 'PLANNED',
  "publicationStatus" text NOT NULL DEFAULT 'DRAFT',
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "worldInfrastructure_kind_check"
    CHECK ("kind" IN ('TOWER', 'ORBITAL_SATELLITE', 'GLOBAL_HEADQUARTERS', 'BUILDING', 'WORKSHOP', 'WAREHOUSE', 'VEHICLE', 'EQUIPMENT', 'STORE', 'FACILITY')),
  CONSTRAINT "worldInfrastructure_operationalStatus_check"
    CHECK ("operationalStatus" IN ('PLANNED', 'ACTIVE', 'INACTIVE', 'MAINTENANCE', 'DAMAGED')),
  CONSTRAINT "worldInfrastructure_publicationStatus_check"
    CHECK ("publicationStatus" IN ('DRAFT', 'PUBLISHED', 'ARCHIVED')),
  CONSTRAINT "worldInfrastructure_worldLocationId_fkey"
    FOREIGN KEY ("worldLocationId") REFERENCES public."worldLocation"("id")
    ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "worldInfrastructure_businessId_fkey"
    FOREIGN KEY ("businessId") REFERENCES public.business("id")
    ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS "worldInfrastructure_kind_operationalStatus_idx"
  ON public."worldInfrastructure" ("kind", "operationalStatus");
CREATE INDEX IF NOT EXISTS "worldInfrastructure_worldLocationId_idx"
  ON public."worldInfrastructure" ("worldLocationId");
CREATE INDEX IF NOT EXISTS "worldInfrastructure_businessId_idx"
  ON public."worldInfrastructure" ("businessId");
CREATE INDEX IF NOT EXISTS "worldInfrastructure_publicationStatus_idx"
  ON public."worldInfrastructure" ("publicationStatus");

CREATE TABLE IF NOT EXISTS public."worldInfrastructureLink" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sourceId" integer NOT NULL,
  "targetId" integer NOT NULL,
  "linkType" text NOT NULL,
  "operationalStatus" text NOT NULL DEFAULT 'PLANNED',
  "description" text NULL,
  "details" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "worldInfrastructureLink_no_self_link_check"
    CHECK ("sourceId" <> "targetId"),
  CONSTRAINT "worldInfrastructureLink_type_check"
    CHECK ("linkType" IN ('TRANSMISSION', 'BACKHAUL', 'SATELLITE_UPLINK', 'SATELLITE_DOWNLINK', 'HEADQUARTERS_CONTROL')),
  CONSTRAINT "worldInfrastructureLink_operationalStatus_check"
    CHECK ("operationalStatus" IN ('PLANNED', 'ACTIVE', 'INACTIVE', 'MAINTENANCE', 'DAMAGED')),
  CONSTRAINT "worldInfrastructureLink_sourceId_fkey"
    FOREIGN KEY ("sourceId") REFERENCES public."worldInfrastructure"("id")
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "worldInfrastructureLink_targetId_fkey"
    FOREIGN KEY ("targetId") REFERENCES public."worldInfrastructure"("id")
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "worldInfrastructureLink_source_target_type_key"
    UNIQUE ("sourceId", "targetId", "linkType")
);

CREATE INDEX IF NOT EXISTS "worldInfrastructureLink_sourceId_operationalStatus_idx"
  ON public."worldInfrastructureLink" ("sourceId", "operationalStatus");
CREATE INDEX IF NOT EXISTS "worldInfrastructureLink_targetId_operationalStatus_idx"
  ON public."worldInfrastructureLink" ("targetId", "operationalStatus");

ALTER TABLE public."worldInfrastructure" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."worldInfrastructureLink" ENABLE ROW LEVEL SECURITY;
